package com.bookstore.bike.repo; import com.bookstore.bike.entity.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.time.Instant; import java.util.*;
public interface BookingRepository extends JpaRepository<Booking,Long>{List<Booking> findByStudentIdOrderByStartAtDesc(Long id); @Query("select count(b)>0 from Booking b where b.bike.id=:bike and b.status in ('PENDING','CONFIRMED','ACTIVE') and b.startAt < :endAt and b.endAt > :startAt") boolean overlaps(@Param("bike") Long bike,@Param("startAt") Instant startAt,@Param("endAt") Instant endAt);}
